#include <iostream>
#include <unordered_map>
using namespace std;

int elementRemoval(int N, int K, int A[]){
    int result = -404;
    unordered_map<int, int> freq;
    for(int i = 0; i < N; i++){
        freq[A[i]]++;
    }
    result = 0;
    for(auto &entry : freq){
        int frequency = entry.second;
        result += (frequency % K);
    }
    return result;
}

int main(){
    int N, K;
    if (!(cin >> N >> K)) return 0;
    int A[N];
    for(int i = 0; i < N; i++) cin >> A[i];
    cout << elementRemoval(N, K, A);
    return 0;
}
